export const MAX_SEATS = 10;
export const COUCH_ROW = 15;
export const COUCH_PRICE = 89;

export interface SeatPosition {
  row: number;
  column: number;
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): SeatPosition {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat identifier: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function compareSeatIds(a: string, b: string): number {
  const pa = parseSeatId(a);
  const pb = parseSeatId(b);
  return pa.row - pb.row || pa.column - pb.column;
}

export function sortSeatIds(ids: string[]): string[] {
  return [...ids].sort(compareSeatIds);
}

export function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function seatPrice(row: number): number {
  if (row <= 5) {
    return 25;
  }
  if (row <= 10) {
    return 32;
  }
  return 39;
}

export function couchIds(startColumn: number): [string, string] {
  return [seatId(COUCH_ROW, startColumn), seatId(COUCH_ROW, startColumn + 1)];
}

export interface SeatItem {
  row: number;
  ids: string[];
  label: string;
  price: number;
}

export function bookedItems(seats: string[]): SeatItem[] {
  const sorted = sortSeatIds(seats);
  const items: SeatItem[] = [];
  const used = new Set<string>();
  for (const id of sorted) {
    if (used.has(id)) {
      continue;
    }
    const { row, column } = parseSeatId(id);
    if (row === COUCH_ROW) {
      const startColumn = column % 2 === 1 ? column : column - 1;
      const ids = couchIds(startColumn);
      ids.forEach((seat) => used.add(seat));
      items.push({ row, ids, label: `Couch ${startColumn}-${startColumn + 1}`, price: COUCH_PRICE });
    } else {
      used.add(id);
      items.push({ row, ids: [id], label: String(column), price: seatPrice(row) });
    }
  }
  return items;
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export function toggleSeats(
  current: string[],
  ids: string[],
): { seats: string[]; exceedsLimit: boolean } {
  const selected = ids.every((id) => current.includes(id));
  if (selected) {
    return { seats: current.filter((id) => !ids.includes(id)), exceedsLimit: false };
  }
  if (current.length + ids.length > MAX_SEATS) {
    return { seats: current, exceedsLimit: true };
  }
  return { seats: [...current, ...ids], exceedsLimit: false };
}

$available: #2e7d32;
$selected: #f9a825;
$unavailable: #c62828;
$accessible: #1565c0;

@mixin seat-state($color) {
  background-color: $color;

  &:hover,
  &:focus,
  &:focus-visible,
  &:active,
  &:disabled {
    background-color: $color;
  }
}

.page {
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px;
  box-sizing: border-box;
  text-align: center;
}

.subtitle {
  color: #555;
  margin: 4px 0 12px;
}

.limit {
  margin: 0 0 16px;
}

.auditorium {
  display: inline-block;
}

.screen {
  background: #e0e0e0;
  border-radius: 4px;
  padding: 6px 0;
  margin-bottom: 16px;
  font-weight: 500;
  letter-spacing: 4px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.seat-row {
  display: grid;
  grid-template-columns: 32px repeat(4, 36px) 80px repeat(16, 36px) 80px repeat(4, 36px) 32px;
  align-items: center;
  justify-items: stretch;
}

.row-label {
  font-size: 13px;
  color: #555;
}

.aisle {
  height: 100%;
}

.seat,
.couch {
  height: 32px;
  margin: 2px;
  border: none;
  border-radius: 4px 4px 2px 2px;
  color: #fff;
  font-size: 11px;
  padding: 0;
  cursor: pointer;

  &[data-state='available'] {
    @include seat-state($available);
  }

  &[data-state='selected'] {
    @include seat-state($selected);
    color: #212121;
  }

  &[data-state='unavailable'] {
    @include seat-state($unavailable);
    cursor: not-allowed;
  }

  &[data-state='accessible'] {
    @include seat-state($accessible);
  }
}

.couch {
  font-weight: 500;
}

.legend {
  display: flex;
  justify-content: center;
  gap: 24px;
  list-style: none;
  padding: 0;
  margin: 16px 0;
}

.legend li {
  display: flex;
  align-items: center;
  gap: 8px;
}

.swatch {
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 3px;

  &.available { background: #2e7d32; }
  &.selected { background: #f9a825; }
  &.unavailable { background: #c62828; }
  &.accessible { background: #1565c0; }
}

.selected-seats {
  margin: 16px auto;
  text-align: left;
  display: inline-block;

  p {
    margin: 4px 0;
  }
}

.actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 16px;
}

import { HttpClient } from '@angular/common/http';
import { Component, computed, inject, input, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { Router } from '@angular/router';
import { map, switchMap } from 'rxjs';
import { API_URL } from '../api';
import { BookingService } from '../booking.service';
import { showDate } from '../dates';
import { Movie, Screening } from '../models';
import { ToastService } from '../toast.service';
import {
  COUCH_ROW,
  couchIds,
  isAccessible,
  MAX_SEATS,
  parseSeatId,
  seatId,
  toggleSeats,
} from '../seats';

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export interface SeatView {
  id: string;
  row: number;
  column: number;
  track: number;
  state: SeatState;
}

export interface CouchView {
  row: number;
  startColumn: number;
  endColumn: number;
  track: number;
  state: SeatState;
  ids: [string, string];
}

export interface RowView {
  number: number;
  seats: SeatView[];
  couches: CouchView[];
}

export interface SelectedRow {
  row: number;
  text: string;
}

const LEFT_LABEL_TRACK = 1;
const LEFT_AISLE_TRACK = 6;
const RIGHT_AISLE_TRACK = 23;
const RIGHT_LABEL_TRACK = 28;

export function columnTrack(column: number): number {
  if (column <= 4) {
    return column + 1;
  }
  if (column <= 20) {
    return column + 2;
  }
  return column + 3;
}

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.component.html',
  styleUrl: './seat-selection.component.scss',
})
export class SeatSelectionComponent {
  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);
  private readonly booking = inject(BookingService);
  private readonly toast = inject(ToastService);

  readonly id = input.required<string>();

  readonly screening = signal<Screening | null>(null);
  readonly movie = signal<Movie | null>(null);

  readonly subtitle = computed(() => {
    const screening = this.screening();
    return screening ? `Show Date: ${showDate(screening.date, screening.time)}` : '';
  });

  readonly selectedSeats = computed(() => this.booking.booking()?.seats ?? []);
  readonly selectedCount = computed(() => this.selectedSeats().length);

  readonly selectedRows = computed<SelectedRow[]>(() => {
    const byRow = new Map<number, number[]>();
    for (const id of this.selectedSeats()) {
      const { row, column } = parseSeatId(id);
      byRow.set(row, [...(byRow.get(row) ?? []), column]);
    }
    return [...byRow.entries()]
      .sort(([a], [b]) => a - b)
      .map(([row, columns]) => {
        const sorted = [...columns].sort((a, b) => a - b);
        const parts = row === COUCH_ROW ? couchLabels(sorted) : sorted.map(String);
        return { row, text: `Row ${row}: ${parts.join(', ')}` };
      });
  });

  readonly rows = computed<RowView[]>(() => {
    const occupied = new Set(this.screening()?.occupiedSeats ?? []);
    const selected = new Set(this.selectedSeats());
    const stateOf = (row: number, column: number): SeatState => {
      const id = seatId(row, column);
      if (occupied.has(id)) {
        return 'unavailable';
      }
      if (selected.has(id)) {
        return 'selected';
      }
      return isAccessible(row, column) ? 'accessible' : 'available';
    };

    return Array.from({ length: 15 }, (_, index) => {
      const number = index + 1;
      if (number === COUCH_ROW) {
        const couches: CouchView[] = [];
        for (let start = 1; start <= 23; start += 2) {
          const ids = couchIds(start);
          let state: SeatState = 'available';
          if (ids.some((id) => occupied.has(id))) {
            state = 'unavailable';
          } else if (ids.every((id) => selected.has(id))) {
            state = 'selected';
          }
          couches.push({
            row: number,
            startColumn: start,
            endColumn: start + 1,
            track: columnTrack(start),
            state,
            ids,
          });
        }
        return { number, seats: [], couches };
      }
      const firstColumn = number <= 10 ? 5 : 1;
      const seats: SeatView[] = [];
      for (let column = firstColumn; column <= 24; column++) {
        seats.push({
          id: seatId(number, column),
          row: number,
          column,
          track: columnTrack(column),
          state: stateOf(number, column),
        });
      }
      return { number, seats, couches: [] };
    });
  });

  readonly leftAisleTrack = LEFT_AISLE_TRACK;
  readonly rightAisleTrack = RIGHT_AISLE_TRACK;
  readonly leftLabelTrack = LEFT_LABEL_TRACK;
  readonly rightLabelTrack = RIGHT_LABEL_TRACK;

  constructor() {
    toObservable(this.id)
      .pipe(
        switchMap((id) =>
          this.http.get<Screening>(`${API_URL}/screenings/${id}`).pipe(
            switchMap((screening) =>
              this.http
                .get<Movie>(`${API_URL}/movies/${screening.movieId}`)
                .pipe(map((movie) => ({ screening, movie }))),
            ),
          ),
        ),
        takeUntilDestroyed(),
      )
      .subscribe({
        next: ({ screening, movie }) => {
          this.screening.set(screening);
          this.movie.set(movie);
          const current = this.booking.booking();
          if (!current || current.screeningId !== screening.id || current.paidEmail !== null) {
            this.booking.start(screening.id);
          }
        },
        error: () => this.router.navigate(['/']),
      });
  }

  onSeatClick(state: SeatState, ids: string[]): void {
    if (state === 'unavailable') {
      return;
    }
    const result = toggleSeats(this.selectedSeats(), ids);
    if (result.exceedsLimit) {
      this.toast.show(`Maximum ${MAX_SEATS} seats per booking`);
      return;
    }
    this.booking.update({ seats: result.seats });
  }

  cancel(): void {
    this.booking.clear();
    this.router.navigate(['/']);
  }

  continue(): void {
    if (this.selectedCount() === 0) {
      return;
    }
    this.router.navigate(['/screenings', this.id(), 'summary']);
  }
}

function couchLabels(columns: number[]): string[] {
  const starts = [...new Set(columns.map((column) => (column % 2 === 1 ? column : column - 1)))];
  return starts.map((start) => `${start}-${start + 1}`);
}

import { Route } from '@angular/router';
import { CheckoutComponent } from './checkout/checkout.component';
import { ConfirmationComponent } from './confirmation/confirmation.component';
import { bookingInProgressGuard, paidBookingGuard } from './guards';
import { MovieListComponent } from './movie-list/movie-list.component';
import { SeatSelectionComponent } from './seat-selection/seat-selection.component';
import { SummaryComponent } from './summary/summary.component';

export const appRoutes: Route[] = [
  { path: '', component: MovieListComponent },
  { path: 'screenings/:id/seats', component: SeatSelectionComponent },
  { path: 'screenings/:id/summary', component: SummaryComponent, canActivate: [bookingInProgressGuard] },
  { path: 'screenings/:id/checkout', component: CheckoutComponent, canActivate: [bookingInProgressGuard] },
  { path: 'confirmation', component: ConfirmationComponent, canActivate: [paidBookingGuard] },
  { path: '**', redirectTo: '' },
];

