file.content:
export const MAX_SEATS = 10;
export const COUCH_ROW = 15;
export const COUCH_PRICE = 89;

export interface SeatPosition {
  row: number;
  column: number;
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): SeatPosition {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat identifier: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function compareSeatIds(a: string, b: string): number {
  const pa = parseSeatId(a);
  const pb = parseSeatId(b);
  return pa.row - pb.row || pa.column - pb.column;
}

export function sortSeatIds(ids: string[]): string[] {
  return [...ids].sort(compareSeatIds);
}

export function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function seatPrice(row: number): number {
  if (row <= 5) {
    return 25;
  }
  if (row <= 10) {
    return 32;
  }
  return 39;
}

export function couchIds(startColumn: number): [string, string] {
  return [seatId(COUCH_ROW, startColumn), seatId(COUCH_ROW, startColumn + 1)];
}

export interface SeatItem {
  row: number;
  ids: string[];
  label: string;
  price: number;
}

export function bookedItems(seats: string[]): SeatItem[] {
  const sorted = sortSeatIds(seats);
  const items: SeatItem[] = [];
  const used = new Set<string>();
  for (const id of sorted) {
    if (used.has(id)) {
      continue;
    }
    const { row, column } = parseSeatId(id);
    if (row === COUCH_ROW) {
      const startColumn = column % 2 === 1 ? column : column - 1;
      const ids = couchIds(startColumn);
      ids.forEach((seat) => used.add(seat));
      items.push({ row, ids, label: `Couch ${startColumn}-${startColumn + 1}`, price: COUCH_PRICE });
    } else {
      used.add(id);
      items.push({ row, ids: [id], label: String(column), price: seatPrice(row) });
    }
  }
  return items;
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export function toggleSeats(
  current: string[],
  ids: string[],
): { seats: string[]; exceedsLimit: boolean } {
  const selected = ids.every((id) => current.includes(id));
  if (selected) {
    return { seats: current.filter((id) => !ids.includes(id)), exceedsLimit: false };
  }
  if (current.length + ids.length > MAX_SEATS) {
    return { seats: current, exceedsLimit: true };
  }
  return { seats: [...current, ...ids], exceedsLimit: false };
}

import { Route } from '@angular/router';
import { CheckoutComponent } from './checkout/checkout.component';
import { ConfirmationComponent } from './confirmation/confirmation.component';
import { bookingInProgressGuard, paidBookingGuard } from './guards';
import { MovieListComponent } from './movie-list/movie-list.component';
import { SeatSelectionComponent } from './seat-selection/seat-selection.component';
import { SummaryComponent } from './summary/summary.component';

export const appRoutes: Route[] = [
  { path: '', component: MovieListComponent },
  { path: 'screenings/:id/seats', component: SeatSelectionComponent },
  { path: 'screenings/:id/summary', component: SummaryComponent, canActivate: [bookingInProgressGuard] },
  { path: 'screenings/:id/checkout', component: CheckoutComponent, canActivate: [bookingInProgressGuard] },
  { path: 'confirmation', component: ConfirmationComponent, canActivate: [paidBookingGuard] },
  { path: '**', redirectTo: '' },
];

$available: #2e7d32;
$selected: #f9a825;
$unavailable: #c62828;
$accessible: #1565c0;

@mixin seat-state($color) {
  background-color: $color;

  &:hover,
  &:focus,
  &:focus-visible,
  &:active,
  &:disabled {
    background-color: $color;
  }
}

.page {
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px;
  box-sizing: border-box;
  text-align: center;
}

.subtitle {
  color: #555;
  margin: 4px 0 12px;
}

.limit {
  margin: 0 0 16px;
}

.auditorium {
  display: inline-block;
}

.screen {
  background: #e0e0e0;
  border-radius: 4px;
  padding: 6px 0;
  margin-bottom: 16px;
  font-weight: 500;
  letter-spacing: 4px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.seat-row {
  display: grid;
  grid-template-columns: 32px repeat(4, 36px) 80px repeat(16, 36px) 80px repeat(4, 36px) 32px;
  align-items: center;
  justify-items: stretch;
}

.row-label {
  font-size: 13px;
  color: #555;
}

.aisle {
  height: 100%;
}

.seat,
.couch {
  height: 32px;
  margin: 2px;
  border: none;
  border-radius: 4px 4px 2px 2px;
  color: #fff;
  font-size: 11px;
  padding: 0;
  cursor: pointer;

  &[data-state='available'] {
    @include seat-state($available);
  }

  &[data-state='selected'] {
    @include seat-state($selected);
    color: #212121;
  }

  &[data-state='unavailable'] {
    @include seat-state($unavailable);
    cursor: not-allowed;
  }

  &[data-state='accessible'] {
    @include seat-state($accessible);
  }
}

.couch {
  font-weight: 500;
}

.legend {
  display: flex;
  justify-content: center;
  gap: 24px;
  list-style: none;
  padding: 0;
  margin: 16px 0;
}

.legend li {
  display: flex;
  align-items: center;
  gap: 8px;
}

.swatch {
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 3px;

  &.available { background: #2e7d32; }
  &.selected { background: #f9a825; }
  &.unavailable { background: #c62828; }
  &.accessible { background: #1565c0; }
}

.selected-seats {
  margin: 16px auto;
  text-align: left;
  display: inline-block;

  p {
    margin: 4px 0;
  }
}

.actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 16px;
}

